WHERE r.driver_id = #{f.driverId} AND r.id <= #{f.snapshotId}

  AND r.status IN (2,3,4)
  AND r.status = 5
  AND r.status = 6

AND  >= #{f.start}
AND  < #{f.end}

mapper.select:
SELECT  
WHERE r.driver_id=#{driverId} AND r.status=5 AND r.finished_at >= #{start} AND r.finished_at < #{end}
ORDER BY r.finished_at DESC, r.id DESC LIMIT 1
